#include "commerce.hpp"
#include <iostream>
int main(){using namespace perekup;std::string line;while(std::getline(std::cin,line)){try{auto q=Json::parse(line);Bank b([]{return .5;});b.balance=100000000;b.now=1000000;auto offer=q.at("offer");auto id=offer.at("id").get<std::string>();Commerce c(b,{{id,offer}});c.state["discounts"][id]=q.value("discount",false);if(q.value("inspected",false))c.state["inspections"][id]={{"paidAt",0}};auto quote=commerceQuote(offer,c.state,q.value("equipment",false),q.value("fx",1.),q.value("dealerFactor",1.));Json stages=Json::array();auto o=c.place(id,{{"fullName","Игрок"}},"home",true,false,true,q.value("equipment",false),"silver","Тест",q.value("fx",1.),q.value("dealerFactor",1.));auto record=[&]{stages.push_back({{"orders",c.state["orders"]},{"balance",b.balance},{"revision",c.state["revision"]}});};record();if(!o.is_null()){b.now=1000000+60*day;c.tick();record();c.payCustoms(o.at("id"),"Тест");record();b.now+=5*day;c.tick();record();}std::cout<<Json({{"quote",quote},{"stages",stages}}).dump()<<'\n';}catch(const std::exception& e){std::cout<<Json({{"error",e.what()}}).dump()<<'\n';}}}
